INSERT INTO `zd_content_data` (`list`, `list_name`, `script`, `table_head`, `table`) VALUES ('log','zd_system_log','function Del(addr) \r\n{\r\n	art.dialog.confirm(\'你确定要删除这条消息吗？\', function () {\r\n		window.location.href=\'http://\' + window.location.host + addr;\r\n		//art.dialog.content(\'http://\' + window.location.host + addr);// 填充对话框内容\r\n		//art.dialog.open(\'http://\' + window.location.host + addr)\r\n		//myDialog.dialog.close();\r\n    //art.dialog.tips(\'执行确定操作\');\r\n}, function () {\r\n	art.dialog.close();\r\n    art.dialog.tips(\'操作被用户取消！\');\r\n});\r\n}\r\n\r\nfunction info(message) {\r\n		art.dialog.tips(message,10);}','<div class=\"box\"><div class=\"box-header with-border\"><strong>系统日志</strong></div><input name=\'d\' type=\'hidden\' value=\'systemlog\'>\r\n        <div class=\"box-body no-padding\"><div class=\"mailbox-controls\">\r\n<button type=\"button\" class=\"btn btn-default btn-sm checkbox-toggle\" name=\"checkall\" id=\"checkall\" checkfor=\"id[]\" title=\"全选\" onclick=\"selectAllDels();\"><i class=\"fa fa-square-o\"></i></button>\r\n							<button type=\"submit\" class=\"btn btn-default btn-sm waves-effect waves-light\" title=\"批量删除\" ><i class=\"fa fa-trash\" ></i></button>\r\n							<button type=\"button\" class=\"btn btn-default btn-sm waves-effect waves-light\" title=\"刷新\" onclick=\"location.reload();\"><i class=\"fa fa-refresh\"></i></button>\r\n        </div>\r\n        <div class=\"table-responsive mailbox-messages\">\r\n        <table class=\"table table-hover table-striped\">\r\n        <thead><tr><th>选择</th><th>请求方式</th><th style=\'text-align:center\'>操作内容</th><th style=\'text-align:center\'>操作ip</th><th>时间</th><th>操作</th></tr></thead>','<tr><td><input type=\'checkbox\' value=\'{id}\' name=\'id[]\' style=\"display: inline-block;*display: inline;vertical-align: middle;\r\nmargin: 0;padding: 0;width: 18px;\r\nheight: 18px;border: none;cursor: pointer;\r\n\"></td><td class=\"mailbox-name\">&nbsp;&nbsp;{method}</td><td align=center class=\"mailbox-name\"><a href=\'javascript:info(\"{data}<br/>操作IP：{ip^&ipdata}&nbsp;&nbsp;操作时间：{time}\")\'>点击查看</td><td style=\'text-align:center\' class=\"mailbox-name\">{ip^&ipdata}</td><td class=\"mailbox-name\">{time}</td><td class=\"mailbox-name\">&nbsp;<a class=\'btn btn-xs waves-effect waves-light\' href=\'#\' onclick=\"javascript:Del(\'$_SERVER[PHP_SELF]?$_SERVER[QUERY_STRING]/id{id} \')\">删除</a></td></tr>'),('report','report','function info(message) { art.dialog.tips(message,5); }\r\n	\r\nfunction Del(addr) \r\n{\r\n	art.dialog.confirm(\'你确定要删除这条内容吗？\', function () {\r\n		window.location.href=\'http://\' + window.location.host + addr;\r\n		//art.dialog.content(\'http://\' + window.location.host + addr);// 填充对话框内容\r\n		//art.dialog.open(\'http://\' + window.location.host + addr)\r\n		//myDialog.dialog.close();\r\n    //art.dialog.tips(\'执行确定操作\');\r\n}, function () {\r\n	art.dialog.close();\r\n    art.dialog.tips(\'操作被用户取消！\');\r\n});\r\n}','<div class=\"panel-head\"><strong>建议与意见</strong></div>\r\n        <div class=\"padding border-bottom\">\r\n            <input type=\"button\" class=\"button button-small checkall\" name=\"checkall\" checkfor=\"id[]\" value=\"全选\" />\r\n            <input type=\"submit\" class=\"button button-small border-yellow\" value=\"批量删除\" />\r\n        </div>\r\n        <table class=\"table table-hover\">\r\n        	<tr><th width=\"1%\"></th><th width=\"8%\">ID</th><th width=\"13%\">提交时间</th><th width=\"13%\">联系方式</th><th width=\"16%\">类型</th><th width=\"14%\">内容</th><th width=\"14%\">操作</th></tr>','<tr><td></td><td><input type=\'checkbox\' name=\'id[]\' value=\'{id}\'>&nbsp;&nbsp;{id}</td><td>{time}</td><td>{address}</td><td>{type}</td><td><a href=\'javascript:info(\"{data}\")\'>点击查看</td><td>&nbsp;<a class=\'button border-yellow button-little\' href=# onclick=\"javascript:Del(\'$_SERVER[PHP_SELF]?$_SERVER[QUERY_STRING]/id{id}\')\\\">删除</a>\";'),('soft','zd_software','function Del(addr) \r\n{\r\n	art.dialog.confirm(\'你确定要删除这条消息吗？\', function () {\r\n		window.location.href=\'http://\' + window.location.host + addr;\r\n		//art.dialog.content(\'http://\' + window.location.host + addr);// 填充对话框内容\r\n		//art.dialog.open(\'http://\' + window.location.host + addr)\r\n		//myDialog.dialog.close();\r\n    //art.dialog.tips(\'执行确定操作\');\r\n}, function () {\r\n	art.dialog.close();\r\n    art.dialog.tips(\'操作被用户取消！\');\r\n});\r\n}\r\n\r\nfunction info(message) {\r\n		art.dialog.tips(message,10);}\r\n\r\nfunction SoftManager(action,softid)\r\n{\r\n		if(action == \'\' || softid == \'\')\r\n		{ info(\'参数错误！\'); }\r\n		\r\n		switch(action)\r\n		{\r\n			case \'add\':\r\n				art.dialog.open(\'system/SoftManager.php?m=add\', {title: \'新增软件\',width: 900 , height: 455});\r\n				break;\r\n				\r\n			case \'edit\':\r\n				art.dialog.open(\'system/SoftManager.php?m=edit&id=\'+softid, {title: \'修改软件\',width: 900, height: 455});\r\n				break;\r\n				\r\n			case \'type_list\':\r\n				art.dialog.open(\'system/soft_typelist.php\', {title: \'分类管理\',width: 420,});\r\n				break;\r\n				\r\n			case \'logoview\':\r\n				art.dialog.open(\'system/softimgview.php?m=logoview&id=\'+softid, {title: \'软件Logo\',width: 420,});\r\n				break;\r\n				\r\n			case \'imgview\':\r\n				art.dialog.open(\'system/softimgview.php?m=imgview&id=\'+softid, {title: \'运行截图管理\',width: 420,});\r\n				break;\r\n		\r\n		}\r\n}','<div class=\"box\"><div class=\"box-header with-border\"><strong>软件管理</strong><input name=\'d\' type=\'hidden\' value=\'zd_software\'><div class=\"box-tools\"><div class=\"has-feedback\"><input type=\"text\" class=\"form-control input-sm\" name=\'search\'><span class=\"fa fa-search form-control-feedback\"></span></div></div></div>\r\n          <div class=\"box-body no-padding\"><div class=\"mailbox-controls\">\r\n        	<button type=\"button\" class=\"btn btn-default btn-sm checkbox-toggle\" name=\"checkall\" id=\"checkall\" checkfor=\"id[]\" title=\"全选\" onclick=\"selectAllDels();\"><i class=\"fa fa-square-o\"></i></button>\r\n                <button type=\"button\" class=\"btn btn-default btn-sm waves-effect waves-light\" title=\"刷新\" onclick=\"location.reload();\"><i class=\"fa fa-refresh\"></i></button>\r\n                <button type=\"button\" class=\"btn btn-default btn-sm waves-effect waves-light\" title=\"新增\" onclick=\"SoftManager(\'add\')\"><i class=\"fa fa-upload\"></i></button>\r\n                <button type=\"button\" class=\"btn btn-default btn-sm waves-effect waves-light\" title=\"分类管理\" onclick=\"SoftManager(\'type_list\')\"><i class=\"fa fa-th-list\"></i></button>\r\n                   <button type=\"submit\" class=\"btn btn-default btn-sm waves-effect waves-light\" title=\"批量删除\" ><i class=\"fa fa-trash\" ></i></button>\r\n        </div>\r\n        <div class=\"table-responsive mailbox-messages\">\r\n        <table class=\"table table-hover table-striped\">\r\n        <thead><tr><th></th><th style=\"text-align:center\">软件名</th><th style=\"text-align:center\">分类</th><th style=\"text-align:center\">版本</th><th style=\"text-align:center\">容量</th><th style=\"text-align:center\">简介</th><th style=\"text-align:center\">更新时间</th><th style=\"text-align:center\">下载数</th><th style=\"text-align:center\">操作</th></tr></thead>','<tr><td><input type=\'checkbox\' id=\"checkbox-1\" name=\'id[]\' value=\'{id}\' style=\"display: inline-block;*display: inline;vertical-align: middle;\r\nmargin: 0;padding: 0;width: 18px;\r\nheight: 18px;border: none;cursor: pointer;\r\n\"></td><td>{softname}</td><td style=\"text-align:center\">{type}</td><td style=\"text-align:center\">{version}</td><td style=\"text-align:center\">{size} KB</td><td>{synopsis}</td><td>{updatetime^&data}</td><td style=\"text-align:center\">{downloadcount}</td><td style=\"text-align:center\"><div class=\"btn-group margin-top-10\"><button type=\"button\" class=\"btn btn-default dropdown-toggle\" data-toggle=\"dropdown\" aria-haspopup=\"true\" aria-expanded=\"false\">Edit <span class=\"caret\"></span></button><ul class=\"dropdown-menu\"><li><a href=\"javascript:SoftManager(\'logoview\',\'{id}\')\">软件Logo</a></li><li><a href=\"javascript:SoftManager(\'imgview\',\'{id}\')\">运行截图</a></li><li><a  href=\"javascript:SoftManager(\'edit\',\'{id}\')\">编辑</a></li><li><a href=\'#\' onclick=\"javascript:Del(\'$_SERVER[PHP_SELF]?$_SERVER[QUERY_STRING]/id{id} \')\">删除</a></li></ul></div></td></tr>');
